/**
 * Pulse SDK v2.0 — Drop-in Analytics. One script tag.
 */
(function() {
  'use strict';
  var scriptEl = document.currentScript || document.getElementsByTagName('script')[document.getElementsByTagName('script').length - 1];
  var C = {
    apiKey: scriptEl.getAttribute('data-api-key') || '',
    endpoint: (scriptEl.getAttribute('data-endpoint') || 'http://localhost:3200').replace(/\/$/, ''),
    debug: scriptEl.getAttribute('data-debug') === 'true',
    flushInterval: parseInt(scriptEl.getAttribute('data-flush-interval')) || 5000
  };
  if (!C.apiKey) { console.warn('[Pulse] No data-api-key. Disabled.'); return; }

  var queue = [], sessionStart = Date.now(), activityCount = 0;
  var currentRoute = location.pathname + location.hash, previousRoute = '', routeEnteredAt = Date.now();
  var userId = 'usr_' + Math.abs(hsh('anon_' + navigator.userAgent)).toString(16).padStart(8, '0');
  var ctx = {}, ctxDone = false;

  function hsh(s) { var v=0; for(var i=0;i<s.length;i++){v=((v<<5)-v)+s.charCodeAt(i);v=v&v;} return v; }
  function gid() { return 'evt_'+Date.now().toString(36)+'_'+Math.random().toString(36).substr(2,6); }
  function log() { if(C.debug) console.log.apply(console,['[Pulse]'].concat([].slice.call(arguments))); }
  function excl(u) { return u.indexOf(C.endpoint)!==-1; }
  function svc(u) { try{var p=new URL(u).pathname.split('/').filter(Boolean);return p.find(function(x){return !x.match(/^v\d+$/);})||p[0]||'unknown';}catch(e){return 'unknown';} }

  // ─── CONTEXT: read from window.__pulse_context (set by host app) ──
  function readContext() {
    if (ctxDone) return;
    var s = window.__pulse_context;
    if (!s || typeof s !== 'object') return;
    try {
      var ud = s.userData;
      if (ud) {
        if (ud.user_id) { ctx.userId = ud.user_id; userId = 'usr_' + Math.abs(hsh(String(ud.user_id))).toString(16).padStart(8,'0'); }
        if (ud.email_address) ctx.email = 'h_' + Math.abs(hsh(ud.email_address)).toString(16);
        if (ud.first_name) ctx.firstName = ud.first_name;
        if (ud.last_name) ctx.lastName = ud.last_name;
        if (ud.phone) ctx.phone = 'h_' + Math.abs(hsh(ud.phone)).toString(16);
        if (ud.id) ctx.sessionId = String(ud.id).split('%')[0].substring(0,20);
      }
      if (s.appID) ctx.appId = s.appID;
      if (s.businessID) ctx.businessId = s.businessID;
      if (s.meta_tenant) ctx.tenant = s.meta_tenant.METADATA_TENANT || s.meta_tenant;
      var ad = s.appData;
      if (ad) {
        if (ad.loan_id) ctx.loanId = ad.loan_id;
        if (ad.status_id) ctx.statusId = Array.isArray(ad.status_id) ? ad.status_id[0] : ad.status_id;
        var biz = ad.business;
        if (biz && typeof biz === 'object' && !Array.isArray(biz)) biz = biz;
        if (Array.isArray(biz)) biz = biz[0];
        if (biz) {
          if (biz.business_name) ctx.businessName = biz.business_name;
          if (biz.requested_amount || biz.amount) ctx.requestedAmount = biz.requested_amount || biz.amount;
          if (biz.requested_tenure || biz.tenure) ctx.requestedTenure = biz.requested_tenure || biz.tenure;
          if (biz.current_state) ctx.currentState = biz.current_state;
          if (biz.journey_type) ctx.journeyType = biz.journey_type;
        }
      }
      if (ctx.userId || ctx.appId || ctx.sessionId) {
        ctxDone = true;
        log('Context resolved from store:', JSON.stringify(ctx));
      }
    } catch(e) { log('Context read error:', e.message); }
  }

  // Poll for context every 2s until resolved
  var ctxPoller = setInterval(function() { readContext(); if (ctxDone) clearInterval(ctxPoller); }, 2000);

  // ─── TRACK ─────────────────────────────────────────────
  function track(name, type, meta) {
    if (!meta) meta = {};
    readContext(); // try to read context before every track
    if (ctxDone) meta._ctx = ctx;
    queue.push({ eventId:gid(), hashedUserId:userId, featureName:name, eventType:type, sessionDuration:Math.round((Date.now()-sessionStart)/1000), metadata:meta, timestamp:new Date().toISOString() });
    if (queue.length >= 25) flush();
  }

  function flush() {
    if (!queue.length) return;
    var batch = queue.splice(0,25), body = JSON.stringify({apiKey:C.apiKey,events:batch});
    try { if(navigator.sendBeacon) navigator.sendBeacon(C.endpoint+'/api/events/ingest',new Blob([body],{type:'application/json'}));
    else { var x=new XMLHttpRequest();x.open('POST',C.endpoint+'/api/events/ingest',true);x.setRequestHeader('Content-Type','application/json');x.send(body); }
    } catch(e){}
  }

  // ─── XHR + FETCH TRACKING (API calls only, no context extraction) ──
  var _xo=XMLHttpRequest.prototype.open, _xs=XMLHttpRequest.prototype.send;
  XMLHttpRequest.prototype.open=function(m,u){this._pm=m;this._pu=u;this._pt=Date.now();return _xo.apply(this,arguments);};
  XMLHttpRequest.prototype.send=function(){
    var self=this,url=self._pu||'';
    self.addEventListener('loadend',function(){
      if(!excl(url)){var rt=Date.now()-(self._pt||Date.now()),st=self.status||0,s=svc(url),err=st>=400;
      var slug='';try{var uu=new URL(url);slug=uu.searchParams.get('slug')||'';}catch(e){}
      track(err?'http_error':'api_call',err?(st>=500?'api_error':'error'):'api_call',{service:slug||s,slug:slug,method:self._pm||'GET',statusCode:st,responseTime:rt,endpoint:url.split('?')[0],route:currentRoute});}
    });
    return _xs.apply(this,arguments);
  };
  var _ff=window.fetch;
  if(_ff){window.fetch=function(input,init){
    var url=typeof input==='string'?input:(input.url||''),method=(init&&init.method)||'GET';
    if(excl(url))return _ff.apply(this,arguments);
    var start=Date.now();
    return _ff.apply(this,arguments).then(function(r){var rt=Date.now()-start,err=r.status>=400;var slug='';try{var uu=new URL(url);slug=uu.searchParams.get('slug')||'';}catch(e){}track(err?'http_error':'api_call',err?(r.status>=500?'api_error':'error'):'api_call',{service:slug||svc(url),slug:slug,method:method.toUpperCase(),statusCode:r.status,responseTime:rt,endpoint:url.split('?')[0],route:currentRoute});return r;}).catch(function(e){track('http_error','api_error',{service:svc(url),method:method.toUpperCase(),statusCode:0,responseTime:Date.now()-start,endpoint:url.split('?')[0],errorMessage:e.message,route:currentRoute});throw e;});
  };}

  // ─── ROUTES ────────────────────────────────────────────
  function recordPageTime(){if(!currentRoute||!routeEnteredAt)return;var s=Math.round((Date.now()-routeEnteredAt)/1000);if(s>=1)track('page_time','page_time',{route:currentRoute,timeSpentSeconds:s,activitiesOnPage:activityCount});}
  function onRoute(nr){if(nr===currentRoute)return;var p=currentRoute,n=Date.now();recordPageTime();if(p)track('route_change','route_change',{fromRoute:p,toRoute:nr,timeOnPreviousRouteSeconds:routeEnteredAt?Math.round((n-routeEnteredAt)/1000):0,activitiesOnPreviousRoute:activityCount});track('pageview','pageview',{route:nr,referrer:p||'direct'});previousRoute=p;currentRoute=nr;routeEnteredAt=n;activityCount=0;log('Route:',p,'→',nr);}
  var lh=location.href,oP=history.pushState,oR=history.replaceState;
  history.pushState=function(){oP.apply(this,arguments);ck();};history.replaceState=function(){oR.apply(this,arguments);ck();};
  window.addEventListener('popstate',ck);window.addEventListener('hashchange',ck);
  function ck(){var hr=location.href;if(hr!==lh){lh=hr;onRoute(location.pathname+location.hash);}}setInterval(ck,1000);

  // ─── CLICKS + FIELDS ──────────────────────────────────
  document.addEventListener('click',function(e){activityCount++;var t=e.target;if(!t)return;var cl=t.closest?t.closest('button,a,[role="button"],.btn'):null;if(cl||['button','a','input','select'].indexOf((t.tagName||'').toLowerCase())!==-1){var el=cl||t;track('user_click','interaction',{element:(el.tagName||'').toLowerCase(),label:(el.getAttribute('aria-label')||(el.innerText||'').trim().substring(0,60)||el.getAttribute('name')||(el.tagName||'').toLowerCase()),route:currentRoute});}},{capture:true,passive:true});
  document.addEventListener('focusin',function(e){var t=e.target,tg=(t.tagName||'').toLowerCase();if(['input','select','textarea'].indexOf(tg)!==-1){activityCount++;track('field_focus','interaction',{fieldName:t.name||t.id||t.getAttribute('formcontrolname')||'unknown',fieldType:t.type||tg,route:currentRoute});}},{capture:true,passive:true});

  // ─── ERRORS ────────────────────────────────────────────
  window.addEventListener('error',function(e){track('js_error','error',{errorMessage:e.message,errorSource:(e.filename||'?')+':'+(e.lineno||0),route:currentRoute});});
  window.addEventListener('unhandledrejection',function(e){track('unhandled_rejection','error',{errorMessage:(e.reason?(e.reason.message||String(e.reason)):'Unknown').substring(0,500),route:currentRoute});});
  var _ce=console.error;console.error=function(){_ce.apply(console,arguments);try{var m=[].slice.call(arguments).map(function(a){return typeof a==='string'?a:(a instanceof Error?a.message:String(a));}).join(' ').substring(0,500);if(m.indexOf('[Pulse]')===-1)track('console_error','error',{errorMessage:m,route:currentRoute});}catch(e){}};

  // ─── LIFECYCLE ─────────────────────────────────────────
  window.addEventListener('beforeunload',function(){recordPageTime();track('session_end','session_end',{});flush();});
  document.addEventListener('visibilitychange',function(){if(document.visibilityState==='hidden'){recordPageTime();flush();}});
  setInterval(flush,C.flushInterval);

  // ─── PUBLIC API ────────────────────────────────────────
  window.Pulse={track:track,flush:flush,identify:function(id){userId='usr_'+Math.abs(hsh(String(id))).toString(16).padStart(8,'0');},setContext:function(d){window.__pulse_context=d;readContext();},getContext:function(){return ctx;},isContextResolved:function(){return ctxDone;}};

  // ─── INIT ──────────────────────────────────────────────
  track('session_start','session_start',{});
  track('pageview','pageview',{route:currentRoute,referrer:document.referrer||'direct'});
  log('SDK v2.0 — reading context from window.__pulse_context');
})();
